public class JavaRefresherCalculate {
    public static int calculate(int[] numbers) {
        int result = 0;

        for (int number : numbers) {
            if (number > 5) {
                result += number;
            }
        }

        return result;
    }

    public static void main(String[] args) {
        int[] values = {3, 8, 2, 10, 5, 7};
        System.out.println(calculate(values));
    }
}
